const express = require("express");
const app = express();
app.use(express.json());

const users = { "tok-an": { id: 1, name: "An" }, "tok-binh": { id: 2, name: "Bình" } };
const tasks = [];
let nextId = 1;

// Xác thực: Authorization: Bearer <token> -> req.user
app.use((req, res, next) => {
  const m = (req.headers["authorization"] || "").match(/^Bearer (.+)$/);
  req.user = m ? users[m[1]] : undefined;
  next();
});
const requireAuth = (req, res, next) => (req.user ? next() : res.status(401).json({ error: "unauthorized" }));

// Kiểm tra đầu vào theo danh sách cho phép
function validate(body) {
  const errors = [];
  if (!body || typeof body.title !== "string" || body.title.trim().length < 3) errors.push("title >= 3 ký tự");
  return errors;
}

app.post("/tasks", requireAuth, (req, res) => {
  const errors = validate(req.body);
  if (errors.length) return res.status(400).json({ errors });
  const task = { id: nextId++, title: req.body.title.trim(), ownerId: req.user.id, done: false };
  tasks.push(task);
  res.status(201).json(task);
