// CHỈ trả việc của chính người dùng (chống IDOR)
app.get("/tasks", requireAuth, (req, res) => res.json(tasks.filter((t) => t.ownerId === req.user.id)));

app.patch("/tasks/:id", requireAuth, (req, res) => {
  const t = tasks.find((x) => x.id === Number(req.params.id));
  if (!t || t.ownerId !== req.user.id) return res.status(404).json({ error: "not found" });
  t.done = true;
  res.json(t);
});

const call = (method, url, token, body) =>
